// Catalogue lines of the gallery entries of the collection « Les mathématiques contre l'intuition » (issue #28, `#intuition`):
// colliding blocks and the napkin ring. Exhibits: gallery-collisions.js, gallery-napkin.js; the collection page is ../intuition-page.js.
const pair=(fr,en)=>[fr,en];
const base={custom:true,symbol:'◇',group:pair('Contre l’intuition','Against intuition'),formula:'',params:[],duration:12,level:pair('Seconde · Terminale','Grades 10 to 12'),
  prereq:pair('Proportions et racines carrées ; la preuve utilise des aires et un volume.','Ratios and square roots; the proof uses areas and a volume.'),quizState:{}};
export const INTUITION_CURIOSITIES=[
  {...base,id:'collisions',title:pair('Les collisions qui calculent π','Colliding blocks that compute π'),short:pair('Chocs et décimales de π','Collisions and digits of π'),
    intro:pair('Un bloc léger repose contre un mur, un bloc lourd arrive. Compte les chocs : le nombre s’écrit avec les décimales de π.','A light block rests against a wall and a heavy block arrives. Count the collisions: the number is written with the digits of π.'),
    steps:[pair('Devine le nombre de chocs pour deux blocs de même masse, puis vérifie en lançant.','Guess the number of collisions for two blocks of equal mass, then check by running it.'),pair('Multiplie la masse du bloc lourd par 100 à chaque fois (puissances 0, 2, 4, 6) et compare les nombres de chocs.','Multiply the mass of the heavy block by 100 each time (powers 0, 2, 4, 6) and compare the numbers.'),pair('Regarde l’espace des vitesses : chaque choc est un rebond sur un des deux miroirs, et le point tourne sur un cercle.','Look at the velocity space: each collision is a bounce on one of two mirrors, and the point turns on a circle.')],
    quiz:pair('Le bloc lourd pèse un million de fois le bloc léger, qui repose contre le mur. Combien de chocs (entre blocs et contre le mur) auront lieu en tout ?','The heavy block weighs a million times the light block, which rests against the wall. How many collisions (between blocks and against the wall) will happen in all?'),answer:3141,
    explain:pair('On obtient 3141 chocs : ce sont les quatre premiers chiffres de π. Ce n’est pas un hasard. L’énergie cinétique est conservée, donc le point (√m·v₁, √M·v₂) reste sur un cercle. Un choc contre le mur est une symétrie par rapport à un axe, un choc entre blocs une symétrie par rapport à une droite qui fait avec le premier axe l’angle θ = arctan(√(m/M)). Deux symétries font tourner le point de 2θ, et il y a des chocs tant que le point n’a pas fait un demi-tour : le nombre de chocs est ⌈π/θ⌉ − 1. Pour M/m = 100^k, θ est très proche de 10⁻ᵏ, d’où 3, 31, 314, 3141.','There are 3141 collisions: the first four digits of π. This is no accident. Kinetic energy is conserved, so the point (√m·v₁, √M·v₂) stays on a circle. A collision with the wall is a reflection in one axis, a collision between blocks a reflection in a line making the angle θ = arctan(√(m/M)) with the first axis. Two reflections turn the point by 2θ, and collisions go on until the point has made half a turn: the number of collisions is ⌈π/θ⌉ − 1. For M/m = 100^k, θ is very close to 10⁻ᵏ, hence 3, 31, 314, 3141.'),
    history:pair('Galperin · 2003','Galperin · 2003'),
    story:pair('Gregory Galperin décrit ce lien entre billard, collisions et π dans « Playing pool with π » (Regular and Chaotic Dynamics, 2003). Les chocs sont comptés ici par une simulation exacte, événement par événement, jamais pas à pas dans le temps. Le modèle suppose des blocs ponctuels dans leur comportement, sans frottement, des chocs parfaitement élastiques et aucun rebond mou du mur.','Gregory Galperin describes this link between billiards, collisions and π in “Playing pool with π” (Regular and Chaotic Dynamics, 2003). The collisions are counted here by an exact event-by-event simulation, never by time steps. The model assumes frictionless blocks, perfectly elastic collisions and a rigid wall.'),
    source:'https://www.mdpi.com/2227-7390/8/4/509',sourceLabel:pair('Aretxabaleta et al., The Dynamics of Digits: Calculating Pi with Galperin’s Billiards · Mathematics 2020 (anglais)','Aretxabaleta et al., The Dynamics of Digits: Calculating Pi with Galperin’s Billiards · Mathematics 2020'),
    reasoning:{conjecture:pair('Pour une masse 100ᵏ fois plus grande, le nombre de chocs s’écrit avec les k + 1 premiers chiffres de π.','For a mass 100ᵏ times larger, the number of collisions is written with the first k + 1 digits of π.'),
      proof:pair('Théorème : le nombre de chocs est ⌈π/θ⌉ − 1 avec θ = arctan(√(m/M)). La conservation de l’énergie place le point sur un cercle ; les deux types de chocs sont des symétries d’angle θ entre leurs axes ; les chocs cessent quand la direction du point sort de l’angle des chocs possibles. Pour 100ᵏ, arctan(10⁻ᵏ) est un peu plus petit que 10⁻ᵏ, et ⌈π/θ⌉ − 1 donne bien 3, 31, 314, 3141 (vérifié par un calcul exact en fractions pour ces quatre rapports). Pour k plus grand, les premières décimales de π restent obtenues mais la tendance n’est pas une propriété universelle : le raisonnement dit seulement que le nombre est ≈ π × 10ᵏ.','Theorem: the number of collisions is ⌈π/θ⌉ − 1 with θ = arctan(√(m/M)). Energy conservation puts the point on a circle; both kinds of collision are reflections whose axes make the angle θ; collisions stop when the direction of the point leaves the range of possible collisions. For 100ᵏ, arctan(10⁻ᵏ) is slightly less than 10⁻ᵏ, and ⌈π/θ⌉ − 1 does give 3, 31, 314, 3141 (checked by exact fraction arithmetic for these four ratios). The reasoning only says the number is ≈ π × 10ᵏ.'),
      transfer:pair('À tester : un rapport de 10 au lieu de 100 donne-t-il 3 puis 31 puis 314 ? Que vaut π/θ pour un rapport de 10 ?','Try it: does a ratio of 10 instead of 100 give 3, then 31, then 314? What is π/θ for a ratio of 10?')},
    links:['#intuition']},
  {...base,id:'napkin-ring',title:pair('L’anneau de serviette','The napkin ring'),short:pair('Paradoxe de l’anneau de serviette','Napkin-ring paradox'),
    intro:pair('On perce de part en part une grosse sphère et une petite, de sorte que les deux anneaux aient la même hauteur. Lequel contient le plus de matière ?','A large sphere and a small one are drilled right through so that the two rings have the same height. Which holds more material?'),
    steps:[pair('Devine : la grosse sphère donne-t-elle un anneau de plus grand volume ? Lis les deux volumes.','Guess: does the large sphere give a ring of larger volume? Read the two volumes.'),pair('Garde la même hauteur et change les rayons : le volume bouge-t-il ?','Keep the same height and change the radii: does the volume move?'),pair('Passe à « le même trou » : cette fois les volumes diffèrent. Déplace le niveau de la coupe et compare les aires des couronnes.','Switch to “same hole”: now the volumes differ. Move the level of the cut and compare the areas of the annuli.')],
    quiz:pair('On perce une sphère de part en part pour obtenir un anneau de hauteur 6 cm. Quel est son volume en cm³ (arrondi au dixième) ? Le rayon de la sphère n’est pas donné.','A sphere is drilled right through to leave a ring of height 6 cm. What is its volume in cm³ (to the nearest tenth)? The radius of the sphere is not given.'),answer:113.1,tolerance:0.06,
    explain:pair('Le volume est π h³/6 = 36π ≈ 113,1 cm³, quel que soit le rayon. À la hauteur z, la coupe est une couronne de rayon extérieur √(R² − z²) et de rayon intérieur r, avec r² = R² − h²/4. Son aire vaut π(R² − z² − r²) = π(h²/4 − z²) : R a disparu. Deux anneaux de même hauteur ont donc des coupes de même aire à chaque niveau, donc (principe de Cavalieri) le même volume. Avec l’intégrale : V = ∫ de −h/2 à h/2 de π(h²/4 − z²) dz = πh³/6. Si l’on garde le même trou plutôt que la même hauteur, la hauteur change avec R et les volumes diffèrent.','The volume is π h³/6 = 36π ≈ 113.1 cm³, whatever the radius. At height z the cut is an annulus with outer radius √(R² − z²) and inner radius r, where r² = R² − h²/4. Its area is π(R² − z² − r²) = π(h²/4 − z²): R has disappeared. Two rings of the same height therefore have cuts of the same area at every level, so (Cavalieri’s principle) the same volume. With an integral: V = ∫ from −h/2 to h/2 of π(h²/4 − z²) dz = πh³/6. If you keep the same hole instead of the same height, the height changes with R and the volumes differ.'),
    history:pair('Seki Kōwa · XVIIe siècle','Seki Kōwa · 17th century'),
    story:pair('Le problème a été étudié au XVIIe siècle par le mathématicien japonais Seki Kōwa, qui appelait ce solide un « anneau d’arc » (d’après Smith et Mikami, 1914). Il est devenu un classique des cours de calcul intégral. Il ne faut pas le confondre avec le problème du prince Rupert, qui parle aussi de trous dans un solide mais pose une autre question.','The problem was studied in the 17th century by the Japanese mathematician Seki Kōwa, who called this solid an “arc ring” (after Smith and Mikami, 1914). It has become a classic of calculus courses. It is not the same as Prince Rupert’s problem, which also involves holes in a solid but asks a different question.'),
    source:'https://mathworld.wolfram.com/SphericalRing.html',sourceLabel:pair('Spherical Ring · MathWorld (anglais)','Spherical Ring · MathWorld'),
    reasoning:{conjecture:pair('Plus la sphère de départ est grande, plus l’anneau qui reste est volumineux.','The larger the original sphere, the more voluminous the ring that remains.'),
      proof:pair('Théorème : un anneau de hauteur h a pour volume πh³/6, indépendamment de R. Preuve par les coupes : aire π(h²/4 − z²) à la hauteur z, puis intégrale (ou principe de Cavalieri). Le résultat est vérifié sur l’exposition par une intégration numérique indépendante. La conjecture ci-dessus est fausse à hauteur fixée ; elle est vraie à trou fixé.','Theorem: a ring of height h has volume πh³/6, independent of R. Proof by cuts: area π(h²/4 − z²) at height z, then an integral (or Cavalieri’s principle). The result is checked in the exhibit by an independent numerical integration. The conjecture above is false at fixed height; it is true at a fixed hole.'),
      transfer:pair('À calculer : pour h = 2 cm, quel est le volume ? Compare avec la boule de rayon 1 cm : que remarques-tu ? (le trou est alors de rayon nul.)','Compute: for h = 2 cm, what is the volume? Compare with the ball of radius 1 cm: what do you notice? (the hole then has radius zero.)')},
    links:['#intuition']},
  {...base,id:'hundred-boxes',title:pair('Le problème des cent boîtes','The hundred boxes problem'),short:pair('Cent prisonniers et cent boîtes','A hundred prisoners and a hundred boxes'),
    intro:pair('Cent prisonniers, cent boîtes qui cachent leurs numéros. Chacun ouvre cinquante boîtes au plus. Au hasard, ils n’ont pratiquement aucune chance ; avec une bonne méthode, presque une sur trois.','A hundred prisoners, a hundred boxes hiding their numbers. Each opens at most fifty boxes. At random they have practically no chance; with a good method, almost one in three.'),
    steps:[pair('Avec 10 prisonniers, joue le prisonnier 1 : ouvre des boîtes jusqu’à trouver ton numéro, ou jusqu’à cinq boîtes.','With 10 prisoners, play prisoner 1: open boxes until you find your number, or until five boxes.'),pair('Lance « Tous : au hasard » plusieurs fois avec une nouvelle permutation, puis « Tous : en suivant les numéros ». Compare.','Run “All: at random” several times with a new permutation, then “All: following the numbers”. Compare.'),pair('Passe à l’affichage des cycles : cherche le lien entre le plus long cycle et le résultat.','Switch to the cycle view: look for the link between the longest cycle and the result.')],
    quiz:pair('Cent prisonniers, cent boîtes, cinquante ouvertures chacun. Avec la meilleure stratégie connue, quelle est la probabilité que tous les prisonniers réussissent, en pourcentage arrondi à l’unité ?','A hundred prisoners, a hundred boxes, fifty openings each. With the best known strategy, what is the probability that all prisoners succeed, as a percentage rounded to the unit?'),answer:31,tolerance:0.6,
    explain:pair('La probabilité est 1 − (1/51 + 1/52 + … + 1/100) ≈ 0,3118, soit environ 31 %. Chaque prisonnier ouvre sa boîte (celle qui porte son numéro), lit le numéro qu’elle contient et ouvre la boîte portant ce numéro, et ainsi de suite : il suit le cycle de la permutation qui passe par son numéro. Ce cycle finit par revenir à son numéro, donc le prisonnier trouve son numéro au bout de la longueur du cycle. Tous réussissent exactement quand aucun cycle ne dépasse 50. Le nombre de permutations de 100 éléments qui ont un cycle de longueur k > 50 est 100!/k, et ces cas s’excluent entre eux : la probabilité d’échec vaut donc la somme des 1/k pour k de 51 à 100. Si chacun ouvrait ses boîtes au hasard, la probabilité serait (1/2)¹⁰⁰ ≈ 10⁻³⁰.','The probability is 1 − (1/51 + 1/52 + … + 1/100) ≈ 0.3118, about 31%. Each prisoner opens his own box (the one carrying his number), reads the number inside and opens the box with that number, and so on: he follows the cycle of the permutation through his number. This cycle returns to his number, so he finds it after at most the length of the cycle. Everybody succeeds exactly when no cycle is longer than 50. The number of permutations of 100 elements with a cycle of length k > 50 is 100!/k, and these cases exclude one another: the probability of failure is therefore the sum of 1/k for k from 51 to 100. If everybody opened boxes at random, the probability would be (1/2)¹⁰⁰ ≈ 10⁻³⁰.'),
    history:pair('Gál et Miltersen · 2003','Gál and Miltersen · 2003'),
    story:pair('Anna Gál et Peter Bro Miltersen posent le problème en 2003 dans une étude sur les structures de données ; la stratégie du cycle est trouvée par Sven Skyum, collègue de Miltersen. Le modèle suppose que les numéros sont rangés par une permutation tirée au hasard et que les prisonniers ne peuvent pas communiquer une fois les boîtes ouvertes.','Anna Gál and Peter Bro Miltersen posed the problem in 2003 in a study of data structures; the cycle strategy was found by Sven Skyum, a colleague of Miltersen. The model assumes the numbers are arranged by a uniformly random permutation and that the prisoners cannot communicate once the boxes are being opened.'),
    source:'https://mathworld.wolfram.com/100PrisonersProblem.html',sourceLabel:pair('The 100 Prisoners Problem · MathWorld (anglais)','The 100 Prisoners Problem · MathWorld'),
    reasoning:{conjecture:pair('Sans communiquer, les prisonniers ne peuvent pas espérer mieux qu’une chance sur 2¹⁰⁰.','Without communicating, the prisoners cannot hope for better than one chance in 2¹⁰⁰.'),
      proof:pair('Théorème : en suivant les cycles, la probabilité de victoire est 1 − (1/(n/2 + 1) + … + 1/n) ; elle vaut 0,3118… pour n = 100 et reste au-dessus de 1 − ln 2 ≈ 0,3069 pour tout n pair. La conjecture est donc fausse : les décisions des prisonniers ne sont pas indépendantes, car elles dépendent toutes de la même permutation. Les 1 000 parties simulées ne prouvent rien : elles retrouvent seulement une fréquence proche de la valeur exacte, vérifiée ici par un dénombrement exact des permutations sans long cycle.','Theorem: following the cycles, the probability of victory is 1 − (1/(n/2 + 1) + … + 1/n); it is 0.3118… for n = 100 and stays above 1 − ln 2 ≈ 0.3069 for every even n. So the conjecture is false: the prisoners’ decisions are not independent, since they all depend on the same permutation. The simulated 1,000 games prove nothing: they only find a frequency close to the exact value, which is checked here by an exact count of permutations without a long cycle.'),
      transfer:pair('À calculer : avec 10 prisonniers, quelle est la probabilité de victoire par les cycles ? (réponse : 1 − (1/6 + 1/7 + 1/8 + 1/9 + 1/10).)','To compute: with 10 prisoners, what is the probability of victory by cycles? (answer: 1 − (1/6 + 1/7 + 1/8 + 1/9 + 1/10).)')},
    links:['#intuition']},
  {...base,id:'morley',title:pair('Le triangle de Morley','Morley’s triangle'),short:pair('Théorème des trisectrices de Morley','Morley’s trisector theorem'),
    intro:pair('Partage chaque angle d’un triangle en trois angles égaux. Les trisectrices voisines se coupent en trois points : quelle figure dessinent-ils ?','Cut each angle of a triangle into three equal angles. Neighbouring trisectors meet in three points: what figure do they draw?'),
    steps:[pair('Devine la nature du triangle formé par les trois points, avant de lire la moindre mesure.','Guess the kind of triangle formed by the three points before reading any measure.'),pair('Déforme le triangle : très aplati, presque rectangle, presque isocèle. La figure intérieure change-t-elle de forme ?','Deform the triangle: very flat, nearly right-angled, nearly isosceles. Does the inner figure change shape?'),pair('Lis les trois côtés et les trois angles du petit triangle. Qu’est-ce qui change, qu’est-ce qui reste ?','Read the three sides and the three angles of the small triangle. What changes, what stays?')],
    quiz:pair('Les trois points d’intersection des trisectrices voisines d’un triangle forment un triangle. Quelle est la mesure, en degrés, de chacun de ses angles ?','The three intersection points of neighbouring trisectors of a triangle form a triangle. What is the measure, in degrees, of each of its angles?'),answer:60,
    explain:pair('Chaque angle mesure 60° : le triangle est équilatéral, quel que soit le triangle de départ. Sa taille change avec le triangle (son côté vaut 8R·sin(A/3)·sin(B/3)·sin(C/3), où R est le rayon du cercle circonscrit), mais pas sa forme. On le constate en déplaçant les sommets ; on le démontre par un calcul trigonométrique que l’on peut donner au lycée en prolongement, mais qui n’est pas immédiat.','Each angle is 60°: the triangle is equilateral, whatever the starting triangle. Its size changes with the triangle (its side is 8R·sin(A/3)·sin(B/3)·sin(C/3), where R is the circumradius), but not its shape. You see this by moving the vertices; it is proved by a trigonometric computation that can be given as an extension, but it is not immediate.'),
    history:pair('Morley · 1899','Morley · 1899'),
    story:pair('Le théorème a été découvert en 1899 par le mathématicien anglo-américain Frank Morley. Les trisectrices sont tracées ici par le calcul : on ne trisecte pas un angle à la règle et au compas, mais on peut calculer exactement la droite qui le partage en trois.','The theorem was discovered in 1899 by the Anglo-American mathematician Frank Morley. The trisectors are computed here: an angle cannot be trisected with ruler and compass, but the line that cuts it into thirds can be computed exactly.'),
    source:'https://mathworld.wolfram.com/MorleysTheorem.html',sourceLabel:pair('Morley’s Theorem · MathWorld (anglais)','Morley’s Theorem · MathWorld'),
    reasoning:{conjecture:pair('Pour tout triangle, le triangle formé par les points de rencontre des trisectrices voisines est équilatéral.','For every triangle, the triangle formed by the meeting points of neighbouring trisectors is equilateral.'),
      proof:pair('Théorème de Morley (1899), démontré. Ici, l’exposition vérifie la propriété par mesure sur le triangle que l’on déplace, ce qui est une expérience et non une démonstration. La démonstration complète est une extension : une démonstration trigonométrique utilise la loi des sinus et l’égalité sin 3x = 4 sin x sin(60° − x) sin(60° + x). Elle n’est pas élémentaire au sens du programme de lycée.','Morley’s theorem (1899), proved. Here the exhibit checks the property by measuring the triangle you move, which is an experiment, not a proof. The complete proof is an extension: a trigonometric proof uses the law of sines and the identity sin 3x = 4 sin x sin(60° − x) sin(60° + x). It is not elementary in the sense of the high school curriculum.'),
      transfer:pair('À tester : pour un triangle équilatéral de côté 1, quel est le côté du petit triangle ? (indice de calcul : 8R·sin³ 20° avec R = 1/√3.)','Try: for an equilateral triangle of side 1, what is the side of the small triangle? (computation: 8R·sin³ 20° with R = 1/√3.)')},
    links:['#intuition']},
];
